+    const option = argv[index];
+    if (option === '--dist') {
+      options.dist = argv[index + 1];
+      index += 1;
+    } else if (option === '--target') {
+      options.target = argv[index + 1];
+      index += 1;
+    } else if (option === '--repo-root') {
+      options.repoRoot = argv[index + 1];
+      index += 1;
